--
-- Complete MySQL Setup and Data Import Script for AMS Project
--
CREATE DATABASE IF NOT EXISTS project_db;
USE project_db;

-- ----------------------------
-- Table structure and data for `admins`
-- ----------------------------
CREATE TABLE IF NOT EXISTS admins (
    id INT AUTO_INCREMENT PRIMARY KEY,
    first_name VARCHAR(100),
    last_name VARCHAR(100),
    email VARCHAR(100) UNIQUE,
    phone VARCHAR(20),
    password VARCHAR(255),
    work TEXT,
    photo VARCHAR(255),
    role VARCHAR(50),
    dob VARCHAR(50),
    address TEXT,
    city VARCHAR(100),
    state VARCHAR(100),
    pincode VARCHAR(20),
    country VARCHAR(100)
);

REPLACE INTO `admins` (`id`, `first_name`, `last_name`, `email`, `phone`, `password`, `work`, `photo`, `role`, `dob`, `address`, `city`, `state`, `pincode`, `country`) VALUES
